	public int SandsOfTimeExtraChance => sandsOfTimeExtraChance;

	public OrionAstrarium OrionAstrarium => orionAstrarium;

	public void Initialize()
	{
		if (activeEffectsList.Count > 0)
		{
			Debug.Log("-----------------PLAYER EFFECTS Initialize: activeEffectsList.Count > 0 when it shouldnt, cleaning it-----------------------");
			activeEffectsList.Clear();
		}
		AddStartingEffects();
		BoostGainedDuringStartOfTurnDiceDrawing = 0;
		if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.EnableStartingPrefab)
		{
			GameObject gameObject = Object.Instantiate(ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.StartingPrefab, playerGameObjectReference.value.transform);
			if (gameObject.GetComponent<OrionAstrarium>() != null)
			{
				orionAstrarium = gameObject.GetComponent<OrionAstrarium>();
			}
		}
		unitEffectsJoystickInput.InitializeUnitDetailJoystickInput(ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.EnableUnitDetailJoystickInput ? ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.UnitDetailJoystickInput : null);
	}

	public override void AddEffect(Effect effect, int effectAmount, bool effectFeedback = true, bool callEffectsCallbacks = true, GameObject source = null, bool gainingEffectVFXAndSFX = true, int renderLayer = -1, bool ignoreNegatableByEffectEnum = false)
	{
		if (effect == playerEffectsList.AstriumEffect && ReferenceSingleton<OrionOmensHandler>.Instance.GravitationalReagentOmenAction != null)
		{
			effectAmount = ReferenceSingleton<OrionOmensHandler>.Instance.GravitationalReagentOmenAction(effectAmount);
		}
		base.AddEffect(effect, effectAmount, effectFeedback, callEffectsCallbacks, source, gainingEffectVFXAndSFX, renderLayer, ignoreNegatableByEffectEnum);
	}

	public void EndOfBattleInitialize()
	{
		ActivateOnRemoveEffectEndOfBattleCallback();
		RemoveAllEffectWithoutCallbacks();
		if (activeEffectsList.Count > 0)
		{
			Debug.Log("-----------------PLAYER EFFECTS EndOfBattleInitialize: activeEffectsList.Count > 0 when it shouldnt, cleaning it-----------------------");
			activeEffectsList.Clear();
		}
		playerEffectsList.SoulHeat.ResetSoulHeat();
		BoostGainedDuringStartOfTurnDiceDrawing = 0;
		InvokeAlternatives.InvokeAfterMultipleFrames(this, 3, delegate
		{
			AddStartingEffects();
		});
	}

	private void AddStartingEffects()
	{
		for (int i = 0; i < ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.StartingEffects.Length; i++)
		{
			StartingEffect startingEffect = ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.StartingEffects[i];
			AddEffect(startingEffect.Effect, startingEffect.EffectAmount, effectFeedback: false, callEffectsCallbacks: true, null, gainingEffectVFXAndSFX: false);
		}
	}

	public override bool RemoveLightShield()
	{
		new List<bool>();
		int num = IsEffectActiveGetAmount(effectsList.LightShieldEffect, activateFeedback: false);
		if (num > 0)
		{
			if (IsEffectActiveAndDecreaseEffect(effectsList.FortifyEffect, 1))
			{
				return false;
			}
			if (ReferenceSingleton<HeveliusOmensHandler>.Instance.IsGlowingReactorOmenActive())
			{
				DecreaseEffect(effectsList.LightShieldEffect, Mathf.CeilToInt(num / 2));
				return true;
			}
			return base.RemoveLightShield();
		}
		return false;
	}

	public override bool OnBeforeBeforeDrawDicePhaseEffect()
	{
		return new List<bool>
		{
			IsEffectActiveWithActivation(effectsList.RuinEffect, activateFeedback: false),
			IsEffectActiveWithActivation(effectsList.NefariousPulseEffect, activateFeedback: false)
		}.Contains(item: true);
	}

	public override bool OnStartTurnEffects()
	{
		List<bool> list = new List<bool>();
		list.Add(base.OnStartTurnEffects());
		list.Add(IsEffectActiveWithActivation(playerEffectsList.SilencedEffect, activateFeedback: false));
		list.Add(IsEffectActiveWithActivation(playerEffectsList.ParalyzeEffect));
		list.Add(IsEffectActive(playerEffectsList.PlayerBoostEffect));
		list.Add(IsEffectActiveWithActivation(playerEffectsList.FrenzyNextTurnEffect, activateFeedback: false, updateAmount: false));
		list.Add(IsEffectActiveWithActivation(playerEffectsList.HurricaneNextTurnEffect, activateFeedback: false));
		playerEffectsList.SoulHeat.ResetSoulHeat(decreaseInnerWarmth: true);
		list.Add(IsEffectActiveWithActivation(playerEffectsList.BloodySolsticeNextTurnEffect, activateFeedback: false));
		list.Add(IsEffectActiveWithActivation(playerEffectsList.ConcentrationEffect));
		list.Add(IsEffectActiveAndDecreaseEffectByHalf(playerEffectsList.FlammableChakramEffect));
		if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunStats.CurrentBattle.BattleTurnCounter > 1)
		{
			list.Add(IsEffectActiveAndDecreaseEffectByHalf(playerEffectsList.SoulStigmaEffect));
		}
		list.Add(currentCorruptedAnimals.IsCorruptedAnimalWithSilencingAuraWithActivation());
		return list.Contains(item: true);
	}

	public override bool OnEndTurnDecreaseEffects()
	{
		return new List<bool>
		{
			base.OnEndTurnDecreaseEffects(),
			IsEffectActiveAndDecreaseEffect(playerEffectsList.SilencedEffect, 1),
			IsEffectActiveAndDecreaseEffect(effectsList.DisorientedEffect, 1),
			IsEffectActiveRemoveEffect(playerEffectsList.Immobilized),
			IsEffectActiveAndDecreaseEffect(playerEffectsList.ReefSongEffect, 1),
			IsEffectActiveAndDecreaseEffect(playerEffectsList.IridescentLightEffect, 1),
			IsEffectActiveAndDecreaseEffect(playerEffectsList.VowReinforcementEffect, 1),
			IsEffectActiveAndDecreaseEffect(playerEffectsList.ShootingStarEnhanceEffect, 1)
		}.Contains(item: true);
	}

	public override bool OnEndTurnEffects()
	{
		List<bool> list = new List<bool>();
		RemoveEffect(effectsList.ShadowMantleEffect);
		list.Add(IsEffectActiveWithActivation(effectsList.UnholyMistEffect));
		list.Add(base.OnEndTurnEffects());
		list.Add(IsEffectActiveWithActivation(playerEffectsList.InspiredEffect, activateFeedback: false));
		list.Add(IsEffectActiveWithActivation(playerEffectsList.ForcefulStreamEffect));
		list.Add(IsEffectActiveWithActivation(playerEffectsList.SunkenCurseEffect));
		list.Add(IsEffectActiveRemoveEffect(playerEffectsList.DecreaseEmpowerEffect, activateFeedback: false));
		list.Add(IsEffectActiveRemoveEffect(playerEffectsList.FrenzyActiveEffect));
		list.Add(IsEffectActiveWithActivation(playerEffectsList.ChargingAntennasEffect, activateFeedback: false));
		OnEndPlayerTurn.Raise();
		return list.Contains(item: true);
	}

	public override void OnStartCorruptPlayerState()
	{
		InvokeAlternatives.InvokeAfterFrame(this, delegate
		{
			IsEffectActiveWithActivation(playerEffectsList.BloodySolsticeActiveEffect, activateFeedback: false, updateAmount: false);
		});
		base.OnStartCorruptPlayerState();
	}

	public override void OnEndOfAllTurns()
	{
		base.OnEndOfAllTurns();
		IsEffectActiveRemoveEffect(playerEffectsList.IndigoSoulEffect);
		DecreaseEffect(playerEffectsList.NegativeFieldEffect, 1);
		IsEffectActiveRemoveEffect(playerEffectsList.HurricaneActiveEffect);
		IsEffectActiveWithActivation(playerEffectsList.GlimmeringBreezeEffect, activateFeedback: false);
	}

	public override void OnSpecificDiceCasted(Dice dice)
	{
		ActivateDiceSpecificEffects(playerEffectsList.FavorableWindsEffect, dice);
		ActivateDiceSpecificEffects(playerEffectsList.MoonlightEffect, dice);
		IsEffectActiveWithActivation(playerEffectsList.AnomalyLevelNineEffect, activateFeedback: false, updateAmount: false);
		IsEffectActiveWithActivation(playerEffectsList.AnomalyLevelTenEffect, activateFeedback: false, updateAmount: false);
		IsEffectActiveWithActivation(playerEffectsList.AnomalyLevelElevenEffect, activateFeedback: false, updateAmount: false);
		base.OnSpecificDiceCasted(dice);
	}

	public override void OnRuneCasted(RuneInstance runeInstance)
	{
		IsEffectActiveWithActivation(playerEffectsList.ApexInstinctEffect);
		IsEffectActiveWithActivation(playerEffectsList.AnomalyLevelNineEffect, activateFeedback: false, updateAmount: false);
		IsEffectActiveWithActivation(playerEffectsList.AnomalyLevelTenEffect, activateFeedback: false, updateAmount: false);
		IsEffectActiveWithActivation(playerEffectsList.AnomalyLevelElevenEffect, activateFeedback: false, updateAmount: false);
	}

	public override void OnCorruptEffects(GameObject source, int corruptAmount)
	{
		base.OnCorruptEffects(source, corruptAmount);
		if (corruptAmount > 0)
		{
			ReferenceSingleton<MiscOmensHandler>.Instance.OnPlayerOrSentinelsCorruptedDivinePrismAction(corruptAmount);
		}
		if (source != null)
		{
			IsEffectActiveWithActivationWithSource(playerEffectsList.ThornHeveliusLinkEffect, source, activateFeedback: false);
		}
	}

	public void OnPurifyEffectsBeforeCurrentCorruptionUpdate()
	{
		currentCorruptedAnimals.IsAnyWithEnemyDeepnessPresenceWithActivation();
	}

	public void OnEndOfBattleEffects()
	{
		IsEffectActiveRemoveEffect(playerEffectsList.HurricaneActiveEffect);
	}

