	public void ActivatePlayerBoostPurification(int diceDiscardedAmount, bool removeBoost)
	{
		playerEffectsList.PlayerBoostEffect.ActivatePlayerBoostPurification(diceDiscardedAmount, base.gameObject, removeBoost);
	}

	public void IsPlayerBoostActiveRemoveIt()
	{
		if (BoostGainedDuringStartOfTurnDiceDrawing > 0)
		{
			int num = IsEffectActiveGetAmount(playerEffectsList.PlayerBoostEffect, activateFeedback: false) - BoostGainedDuringStartOfTurnDiceDrawing;
			if (num > 0)
			{
				IsEffectActiveAndDecreaseEffect(playerEffectsList.PlayerBoostEffect, num);
			}
			BoostGainedDuringStartOfTurnDiceDrawing = 0;
		}
		else
		{
			IsEffectActiveRemoveEffect(playerEffectsList.PlayerBoostEffect);
		}
	}

