	public void CheckSandsOfTime()
	{
		ResetVariablesBeforeCheckSandsOfTime();
		int num = IsEffectActiveGetAmount(playerEffectsList.SandsOfTimeEffect, activateFeedback: false) + sandsOfTimeExtraChance;
		if (num > 0 || IsEffectActive(playerEffectsList.SandsOfTimeEffect.HourglassMasteryEffect, activateFeedback: false))
		{
			playerEffectsList.SandsOfTimeEffect.CheckSandsOfTime(num, this);
			sandsOfTimeExtraChance = 0;
		}
	}

