	public override void ToggleActionValueModifier(ActionValueModifier actionValueModifier)
	{
		Debug.Log("====TOGGLE ACTION VALUE MODIFIER: " + actionValueModifier.BattleActionInteractionEnum.ToString() + " " + actionValueModifier.ActionValueModifierAmount + " ====");
		ReferenceSingleton<PlayerDiceHandHolder>.Instance.TogglePlayerActionValueModifier(actionValueModifier);
		if (IsEffectActive(playerEffectsList.ReefSongEffect, activateFeedback: false))
		{
			ActionValueModifier actionValueModifier2 = new ActionValueModifier(actionValueModifier.ActionValueModifierAmount + playerEffectsList.ReefSongEffect.IncreaseVirtuesPurificationAmount, actionValueModifier.BattleActionInteractionEnum);
			playerEffectsList.ReefSongEffect.ToggleActionValueModifierOnRunes(actionValueModifier2, runesPanelReference.value.GetComponent<RunesPanel>());
		}
	}

